import { strict as assert } from "node:assert";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { isPaperCitationSnapshot, readPaperEvidence } from "../src/paper-evidence.ts";

// Generated by fixtures/generate-paper-export.py using Paper Agent's pinned PDF runtime.
const fixture = readFileSync(new URL("./fixtures/paper-report.json", import.meta.url));
const encode = (value: unknown) => new TextEncoder().encode(JSON.stringify(value)).buffer;
const exportRecord = () => JSON.parse(fixture.toString("utf8"));
const sha256 = (value: string | Uint8Array) => createHash("sha256").update(value).digest("hex");

function canonical(value: unknown): string {
  if (Array.isArray(value)) return "[" + value.map(canonical).join(",") + "]";
  if (value && typeof value === "object") {
    const record = value as Record<string, unknown>;
    return "{" + Object.keys(record).sort().map(key => JSON.stringify(key) + ":" + canonical(record[key])).join(",") + "}";
  }
  return JSON.stringify(value);
}

test("imports exact frozen citations from a Paper-owned export", async () => {
  const report = exportRecord();
  const imported = await readPaperEvidence(Uint8Array.from(fixture).buffer);
  assert.equal(imported.reportId, report.id);
  assert.equal(imported.title, report.title);
  assert.equal(imported.exportSha256, sha256(fixture));
  assert.deepEqual(imported.citations.map(({ evidence, reference }) => ({
    locator: reference.locator,
    paperId: evidence.paperId,
    passageId: evidence.passageId,
    fileDigest: evidence.fileDigest,
    quote: evidence.quote,
    page: evidence.page,
    span: [evidence.start, evidence.end],
    occurrences: evidence.occurrences,
  })), [
    {
      locator: `pero-app-location://paper-agent/main/report/${report.id}/citation/0`,
      paperId: report.sources[0].id, passageId: report.passages[0].id, fileDigest: report.passages[0].fileDigest,
      quote: "Exact original evidence.", page: 2, span: [13, 37], occurrences: 2,
    },
    {
      locator: `pero-app-location://paper-agent/main/report/${report.id}/citation/1`,
      paperId: report.sources[0].id, passageId: report.passages[0].id, fileDigest: report.passages[0].fileDigest,
      quote: "Second page. Exact original evidence.", page: 2, span: [0, 37], occurrences: 1,
    },
  ]);
  const snapshot = { kind: "paper-report", ...imported.citations[0].evidence };
  assert.equal(isPaperCitationSnapshot(snapshot), true);
  assert.equal(isPaperCitationSnapshot({ ...snapshot, verdict: "PASS" }), false);
});

test("rejects changed frozen records and citations absent from a well-formed passage", async () => {
  const changedReport = exportRecord();
  changedReport.title = "Changed title";
  await assert.rejects(readPaperEvidence(encode(changedReport)), /report ID does not match/);

  const changedPassage = exportRecord();
  changedPassage.passages[0].content += " Changed passage.";
  await assert.rejects(readPaperEvidence(encode(changedPassage)), /passage identity does not match/);

  const { id: _id, createdAt, retrieval, sources, passages, ...report } = exportRecord();
  report.sections[0].evidence[0].quote = "Invented quotation.";
  await assert.rejects(readPaperEvidence(encode({
    ...report, id: sha256(canonical(report)), createdAt, retrieval, sources, passages,
  })), /quote is not exact/);

  await assert.rejects(readPaperEvidence(encode({ ...report, id: sha256(canonical(report)) })), /no frozen PDF retrieval/);
});

test("uses page-relative Unicode code points, not UTF-16 indices", async () => {
  const { id: _id, createdAt, retrieval, sources, passages, ...report } = exportRecord();
  const passage = passages[0];
  passage.content = "🧪\n" + passage.content;
  passage.start = 50;
  const { documentId, page, start, content } = passage;
  passage.id = sha256(canonical({ documentId, page, start, content }));
  retrieval.passageIds[0] = passage.id;
  for (const evidence of report.sections[0].evidence) evidence.passageId = passage.id;
  const imported = await readPaperEvidence(encode({
    ...report, id: sha256(canonical(report)), createdAt, retrieval, sources, passages,
  }));
  assert.deepEqual(imported.citations.map(({ evidence }) => [evidence.start, evidence.end]), [[65, 89], [52, 89]]);
});
